<div class="dashboard-heading"><div><span class="eyebrow">CONTA</span><h2>Meus dados</h2><p>Atualize seus dados pessoais e senha.</p></div></div><form class="panel resource-form" method="post" action="<?= e(url('/minha-conta/perfil')) ?>"><?= csrf_field() ?><input type="hidden" name="_method" value="PUT"><div class="form-grid"><label>Nome<input name="name" required value="<?= e(old('name',$user['name'])) ?>"><?php if(error('name')):?><small class="field-error"><?=e(error('name'))?></small><?php endif;?></label><label>E-mail<input disabled value="<?= e($user['email']) ?>"></label><label>Telefone<input name="phone" inputmode="tel" required value="<?= e(old('phone',$user['phone']??'')) ?>"><?php if(error('phone')):?><small class="field-error"><?=e(error('phone'))?></small><?php endif;?></label><label>CPF/CNPJ<input name="document" inputmode="numeric" required value="<?= e(old('document',$user['document']??'')) ?>"><?php if(error('document')):?><small class="field-error"><?=e(error('document'))?></small><?php endif;?></label><label>Senha atual<input type="password" name="current_password" autocomplete="current-password"><small>Obrigatória somente ao trocar a senha.</small><?php if(error('current_password')):?><small class="field-error"><?=e(error('current_password'))?></small><?php endif;?></label><label>Nova senha<input type="password" name="password" minlength="12" autocomplete="new-password"><small>12 caracteres, com maiúscula, minúscula, número e símbolo.</small><?php if(error('password')):?><small class="field-error"><?=e(error('password'))?></small><?php endif;?></label><label>Confirmar nova senha<input type="password" name="password_confirmation" minlength="12" autocomplete="new-password"><?php if(error('password_confirmation')):?><small class="field-error"><?=e(error('password_confirmation'))?></small><?php endif;?></label></div><div class="form-actions"><button class="button button--primary">Salvar meus dados</button></div></form>
